const $=selector=>document.querySelector(selector);
const out=$('#out'),correctField=$('#correct'),problematicField=$('#problematic'),analyze=$('#analyze'),download=$('#download');
let latestReport=null;
const identity=record=>String(record?.imageid||record?.image_id||record?.filename||'').replace(/_+$/,'');
const parseIds=value=>[...new Set(String(value||'').split(/[\s,]+/).map(value=>value.trim().replace(/_+$/,'')).filter(Boolean))];
const valueAt=(record,path)=>path.split('.').reduce((value,key)=>value?.[key],record),rounded=value=>Array.isArray(value)?value.map(rounded):typeof value==='number'?Number(value.toFixed(12)):value;
const fieldPaths=['imageid','sol','site','drive','date_taken','date_received','instrument','camera_model_type','camera_vector','camera_position','xyz','subframe_rect','camera_model_component_list','extended.mast_az','extended.mast_el','extended.sample_type','attitude'];
const MSL_SCLK_REFERENCE=695055846,MSL_SOL_REFERENCE=3352,MSL_SECONDS_PER_SOL=88775.244,solCache=new Map;
function compact(record,classification){const fields=Object.fromEntries(fieldPaths.map(path=>[path,rounded(valueAt(record,path))]).filter(([,value])=>value!==undefined));return{imageId:identity(record),classification,edrVariant:(identity(record).match(/EDR_([A-Z])\d+/i)||[])[1]||null,productClock:(identity(record).match(/EDR_[A-Z](\d+)/i)||[])[1]||null,fields,raw:record}}
function varyingFields(records){return fieldPaths.map(path=>{const values=records.map(record=>rounded(valueAt(record,path))),unique=[...new Set(values.map(value=>JSON.stringify(value)))];return unique.length>1?{path,values}:null}).filter(Boolean)}
function separatingFields(entries){return fieldPaths.map(path=>{const values={};for(const group of ['correct','problematic']){const groupEntries=entries.filter(entry=>entry.classification===group);values[group]=[...new Set(groupEntries.map(entry=>JSON.stringify(rounded(valueAt(entry.record,path)))))]}if(values.correct.length!==1||values.problematic.length!==1||values.correct[0]===undefined||values.problematic[0]===undefined||values.correct[0]===values.problematic[0])return null;return{path,correct:JSON.parse(values.correct[0]),problematic:JSON.parse(values.problematic[0])}}).filter(Boolean)}
async function fetchSol(sol){if(solCache.has(sol))return solCache.get(sol);const request=(async()=>{let records=[],page=0,more=true;while(more){const params=new URLSearchParams({order:'sol asc,date_taken asc',per_page:'100',page:String(page),condition_1:'msl:mission',condition_2:`${sol}:sol:gte`,condition_3:`${sol}:sol:lte`,search:'',extended:''}),response=await fetch(`https://mars.nasa.gov/api/v1/raw_image_items?${params}`),data=await response.json();if(!response.ok)throw Error(`NASA request failed for Sol ${sol}`);records.push(...(data.items||[]));more=Boolean(data.more);page++}return records})();solCache.set(sol,request);return request}
async function findRecord(id){const clock=Number((id.match(/^[A-Z0-9]+_(\d{8,})/i)||[])[1]);if(!Number.isFinite(clock))throw Error(`${id} has no usable spacecraft clock`);const estimated=Math.round(MSL_SOL_REFERENCE+(clock-MSL_SCLK_REFERENCE)/MSL_SECONDS_PER_SOL),sols=Array.from({length:7},(_,index)=>estimated+index-3).filter(sol=>sol>=0),records=(await Promise.all(sols.map(fetchSol))).flat(),exact=records.find(record=>identity(record)===id);if(!exact)throw Error(`${id} was not found in the SCLK-derived Sol window`);return exact}
async function run(){const labels=new Map;for(const id of parseIds(correctField.value))labels.set(id,'correct');for(const id of parseIds(problematicField.value)){if(labels.has(id)){out.textContent=`ERROR: ${id} is listed as both correct and problematic`;return}labels.set(id,'problematic')}const entries=[...labels].map(([id,classification])=>({id,classification}));if(!entries.length){out.textContent='Enter at least one labelled image ID.';return}const correctIds=parseIds(correctField.value),problematicIds=parseIds(problematicField.value);history.replaceState(null,'',`?correct=${encodeURIComponent(correctIds.join(','))}&problematic=${encodeURIComponent(problematicIds.join(','))}`);analyze.disabled=true;out.textContent=`Loading ${entries.length} labelled NASA records…`;try{const loaded=await Promise.all(entries.map(async entry=>({...entry,record:await findRecord(entry.id)})));const summary=loaded.map(entry=>compact(entry.record,entry.classification));latestReport={format:'mars-rover-360-edr-offset-diagnostic/v2',createdAt:new Date().toISOString(),requestedImageIds:{correct:correctIds,problematic:problematicIds},summary:{records:loaded.length,correctRecords:correctIds.length,problematicRecords:problematicIds.length,edrFamilies:[...new Set(summary.map(item=>item.edrVariant).filter(Boolean))],sols:[...new Set(loaded.map(entry=>entry.record.sol))],varyingGeometryRelevantFields:varyingFields(loaded.map(entry=>entry.record)),fieldsWithSingleDistinctValuePerClass:separatingFields(loaded)},records:summary};out.textContent=JSON.stringify(latestReport,null,2);download.disabled=false}catch(error){latestReport=null;download.disabled=true;out.textContent=`ERROR: ${error.message}`}finally{analyze.disabled=false}}
analyze.onclick=run;
download.onclick=()=>{if(!latestReport)return;const href=URL.createObjectURL(new Blob([JSON.stringify(latestReport,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=href;link.download='edr-offset-diagnostic.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(href),1000)};
const params=new URLSearchParams(location.search),legacy=params.get('ids'),correct=params.get('correct'),problematic=params.get('problematic');
if(correct||problematic||legacy){correctField.value=correct||'';problematicField.value=problematic||legacy||'';run()}
